const item = $input.first();
const body = item.json.body || item.json || {};
const headers = item.json.headers || {};
const event = body.event || body.data?.event || body.data || {};
const issue = body.issue || body.data?.issue || event.issue || {};
const project = body.project || body.data?.project || event.project || {};
const actor = body.actor || body.data?.actor || {};
const issueId = issue.id || body.issue_id || event.issue_id || event.groupID || null;
const issueShortId = issue.shortId || issue.short_id || event.short_id || null;
const title = issue.title || event.title || event.message || body.title || body.message || 'Sentry issue';
const culprit = issue.culprit || event.culprit || null;
const environment = event.environment || issue.environment || body.environment || null;
const level = event.level || issue.level || body.level || null;
const url = issue.permalink || body.url || event.web_url || event.url || null;
const projectSlug = project.slug || project.name || body.project_slug || null;
const safeShortId = issueShortId || issueId || 'unknown';
const githubTitle = `[Sentry] ${safeShortId} - ${title}`.slice(0, 250);
const githubBody = [
  '## Sentry issue', '',
  `- Issue: ${safeShortId}`,
  `- Project: ${projectSlug || 'unknown'}`,
  `- Environment: ${environment || 'unknown'}`,
  `- Level: ${level || 'unknown'}`,
  `- Culprit: ${culprit || 'unknown'}`,
  `- URL: ${url || 'not provided'}`, '',
  '## Required handling', '',
  '- Follow AGENTS.md and docs/ORCHESTRATOR.md.',
  '- Reproduce the issue or inspect the latest Sentry event.',
  '- Patch the minimum safe change.',
  '- Run npm run ci when code changes.',
  '- Do not commit, push, deploy, or run destructive actions without owner confirmation.', '',
  'Created automatically by n8n workflow WF-SENTRY-01.'
].join('\n');
return [{ json: { source: 'sentry', receivedAt: new Date().toISOString(), project: projectSlug, issueId, issueShortId, title, culprit, environment, level, url, actor: actor.name || actor.email || null, githubTitle, githubBody, action: 'Review this issue in Sentry, reproduce in DentaGest, patch in repo, run npm run ci, do not commit/push/deploy without confirmation.', headersSeen: Object.keys(headers).sort() } }];
